import {mountMeshes,mountFrame as F} from './mount-meshes.js';
import {bounds,rotateBed} from './mesh.js';
import {affine,apply,rx,rz,rad,scenePoint,sceneBounds,localPoint} from './scene.js';
import {solid} from './solid.js';
import {tripodGeometry,tripodBase,tripodChecks,meshMass,TRIPOD} from './tripod.js';
// Printed parts for the selected options: [part name, bundled variant]. Variants come from cad/simple-mount.scad.
export function mountParts(p){return[...(p.mountBase?[['base',p.mountBase===2?'base-legs':'base']]:[]),['yoke',p.mountBase?'yoke':'yoke-stand'],['upright',p.mountArcLock?'upright-arc':'upright'],['cradle','cradle'],['cheek',p.mountArcLock?'cheek-arc':'cheek']];}
export function appendMount(m){if(!m.p.mountMode)return;
 const p=m.p,turn=q=>rz(q,rad(-p.azimuth)),floor=p.mountBase?0:F.baseT,range=[p.seamJoint?-7.5:-10,100],legs=p.mountBase===2?tripodGeometry(p):null;
 for(const[name,variant]of mountParts(p)){const mesh=variant==='base-legs'?tripodBase(p,legs):mountMeshes[variant];let choice;for(let yaw=0;yaw<180;yaw+=15){const output=rotateBed(mesh,yaw),dim=bounds(output).size;if(dim[0]<=p.bedX-2*p.margin&&dim[1]<=p.bedY-2*p.margin&&dim[2]<=p.bedZ-2){choice={output,dim,yaw};break;}}if(!choice)throw Error('Mount '+name+' exceeds the print volume.');const {output,dim,yaw}=choice;
  const part={id:'mount-'+name,name:'Mount · '+name,mesh,print:output,output,dim,qty:1,kind:'mount',row:-1,bedRotation:yaw,angle:0,supportMeshes:[],spec:{variant,source:'cad/STL/simple-'+variant+'.stl'+(variant==='base-legs'?' + leg sockets (dist/tripod.js)':''),source_sha256:mesh.source_sha256,frame:mesh.frame}};m.parts.push(part);
  // print coordinates -> assembly frame (inverse SCAD print transform) -> world at the selected pose
  const model=q=>apply(mesh.toModel,q),fn=mesh.frame==='cradle'?q=>{const v=rx(model(q),rad(p.elevation));v[2]+=F.axisZ;return turn(v);}:name==='base'?model:q=>turn(model(q));
  m.instances.push({part,a:0,matrix:affine(fn)});
 }
 // Interference at this pose: one solid per part, transformed per instance; only overlapping bounds are intersected.
 const base=new Map(),place=i=>{if(!base.has(i.part))base.set(i.part,solid(i.part.mesh));const s=base.get(i.part).transform(q=>scenePoint(m,i,q)),{min,max}=s.raw.boundingBox();return{id:i.part.id,s,min,max};},touch=(a,b)=>a.min.every((v,k)=>v<=b.max[k]+.01)&&a.max.every((v,k)=>v>=b.min[k]-.01);
 const mounts=m.instances.filter(i=>i.part.kind==='mount').map(place);
 let maxOverlap=0;
 for(const i of m.instances.filter(i=>i.part.kind!=='mount')){const s=place(i);for(const t of mounts){if(!touch(s,t))continue;const overlap=s.s.intersect(t.s).raw.volume();maxOverlap=Math.max(maxOverlap,overlap);if(overlap>.1)throw Error(`${i.part.name} interferes with ${t.id} at this aiming pose. Change elevation or dish settings.`);}}
 // clearances are measured below the lowest mount face: the base bottom (z 0) or, without the base, the yoke plate (z 14)
 const b=sceneBounds(m),lo=rad(range[0]),hi=rad(range[1]),toCradle=q=>{const v=rx(q,-Math.PI/2);v[1]+=F.hubL+16-45**2/(4*m.focal);return v;},points=[];let sweepMin=floor;
 for(const i of m.instances.filter(i=>i.part.kind!=='mount'))for(const q of i.part.mesh.v){const v=toCradle(localPoint(i,q));if(legs)points.push(v);let critical=Math.atan2(v[1],v[2])+Math.PI;while(critical>Math.PI)critical-=2*Math.PI;const angles=[lo,hi,...(critical>=lo&&critical<=hi?[critical]:[])];for(const a of angles)sweepMin=Math.min(sweepMin,F.axisZ+v[1]*Math.sin(a)+v[2]*Math.cos(a));}
 let tripod=null;if(legs){
  // Masses for the tipping check: printed parts, aluminum rods and mast, the feed payload at its focus, and the mount.
  const P=TRIPOD.density,masses=[],fixed=[],cache=new Map(),mass=part=>{if(!cache.has(part))cache.set(part,meshMass(part.mesh));return cache.get(part);};
  for(const i of m.instances){const {volume,centroid}=mass(i.part),g=volume/1000*P.print;if(i.part.kind!=='mount'){masses.push([toCradle(localPoint(i,centroid)),g]);continue;}
   const mesh=i.part.mesh,q=apply(mesh.toModel,centroid);(mesh.frame==='cradle'?masses:fixed).push([q,g]);}
  if(m.feed){const g=m.feed;for(const l of g.legs)masses.push([toCradle(l.lower.map((x,k)=>(x+l.upper[k])/2)),Math.PI*(g.rodDiameter/2)**2*l.cutLength/1000*P.aluminum]);
   if(g.mast?.tube)masses.push([toCradle([0,0,(g.mast.footTop+g.mast.tubeTop)/2]),Math.PI*(g.mast.diameter-1)*g.mast.cutLength/1000*P.aluminum]);
   masses.push([toCradle([0,0,g.bowl?g.bowl.insertFocus:g.secondary?g.secondary.backFocus:g.carrierFace]),p.feedPayload]);}
  tripod={...legs,legs:legs.legs.map(({at,...l})=>l),...tripodChecks(legs,{points,masses,fixed,axisZ:F.axisZ,range,lowest:sweepMin,pose:p})};}
 m.mount={mode:'simple-alt-az',tripod,azimuth:p.azimuth,elevation:p.elevation,base:!!p.mountBase,arcLock:!!p.mountArcLock,parts:mountParts(p).map(([name,variant])=>({id:'mount-'+name,variant})),lowestFace:p.mountBase?'base bottom':'yoke plate bottom',lowestFaceZ:floor,standClearance:Math.max(0,floor-b.min[2]),sweepStandClearance:floor-sweepMin,checkedPose:true,maxOverlap,source:'cad/simple-mount.scad',plateThickness:F.plateT,elevationRange:range};
}
export function mountHardware(m){if(!m.p.mountMode)return[];const base=m.p.mountBase,arc=m.p.mountArcLock,ins=F.insert,up=F.uprightScrews,ch=F.cheekScrews;return[
 ...(base?[{item:'azimuth clamp screw',spec:'M8 × 25 socket head',quantity:1,note:'Nut captured under base; washer and nut listed separately.'}]:[]),
 {item:'elevation clamp bolt',spec:'M8 × 40 hex head',quantity:1,note:'Head sits in the hex pocket inside the cheek; fender washer and wing nut listed separately.'},
 ...(base?[{item:'azimuth washer',spec:'M8 flat washer',quantity:1,note:'Under socket head.'},{item:'azimuth nut',spec:'M8 hex nut',quantity:1,note:'Captured under base.'}]:[]),
 {item:'elevation washer',spec:'M8 fender washer, 24–30 mm OD',quantity:1,note:'Under wing nut.'},
 {item:'elevation nut',spec:'M8 wing nut',quantity:1,note:'Hand-operated clamp.'},
 {item:'mount heat-set insert',spec:`M4 heat-set insert, ${ins.length} mm long or shorter, for a Ø${ins.pilot} mm pilot`,quantity:up.count+ch.count,note:`${up.count} in the upright foot, ${ch.count} in the cheek end face; pilots are ${ins.depth} mm deep. Seat 0.5 mm below the tenon entry face; do not bury the insert to the pilot end.`},
 {item:'upright joint screw',spec:`M4 × ${up.length} flat-head, 90° countersunk (ISO 10642 / DIN 7991)`,quantity:up.count,note:'Up through the yoke plate into the upright inserts; heads flush in the countersinks under the plate.'},
 {item:'cheek joint screw',spec:`M4 × ${ch.length} flat-head, 90° countersunk (ISO 10642 / DIN 7991)`,quantity:ch.count,note:'From the hub face through the cradle plate into the cheek inserts; heads flush, fitted before the dish hub.'},
 ...(arc?[{item:'arc lock bolt',spec:`M6 × ${F.arc.boltLength} hex head (ISO 4017)`,quantity:1,note:'Head captive in the second hex pocket inside the cheek; runs in the upright arc slot.'},{item:'arc lock washer',spec:'M6 flat washer, 12 mm OD (ISO 7089)',quantity:1,note:'Under the nut on the upright outer face. A larger washer fouls the M8 wing nut.'},{item:'arc lock nut',spec:'M6 nyloc nut (ISO 10511)',quantity:1,note:'10 mm wrench. Not a wing nut: its wings would foul the M8 wing nut.'}]:[]),
 ...(base===2?legHardware(m.mount.tripod):[{item:'stand fixing screw',spec:'M5 flat-head / length from stand thickness',quantity:4,note:base?'Through the base; heads must sit below the azimuth bearing face.':'No base: down through the yoke plate countersinks into the stand; heads flush.'}])];}
const legHardware=t=>{const b=t.bolt,f=x=>+x.toFixed(1);return[
 {item:'tripod leg',spec:`Ø${+t.d.toFixed(2)} mm rod, tube or dowel, ${t.minLegLength} mm or longer`,quantity:3,note:`Each sits ${f(t.engagement)} mm deep in its socket. Cut the top end square. ${t.limitedBy==='stability'?'Shorter legs make the dish easier to tip.':'Shorter legs let the dish reach the ground.'}`},
 {item:'leg cross bolt',spec:`M${b.size} × ${b.length} socket head`,quantity:3,note:`Across the socket flats, ${f(b.fromOpenEnd)} mm in from the socket mouth. Push the leg fully home, then drill Ø${b.size+.2} through it using the socket hole as the guide.`},
 {item:'leg bolt nut',spec:`M${b.size} nyloc`,quantity:3},
 {item:'leg bolt washer',spec:`M${b.size} flat washer`,quantity:6,note:'One on each flat face.'}];};
export function mountGuide(m){if(!m.mount)return'';const p=m.p,base=p.mountBase,arc=p.mountArcLock,up=F.uprightScrews,ch=F.cheekScrews,ins=F.insert,names=mountParts(p).map(x=>x[0]),below=base?'the base':'the yoke plate';return `${names.length} printed mount parts: ${names.join(', ')}. Keep the exported print orientations: ${base===2?'base top face down with the leg sockets standing up, ':base?'base top face down, ':''}yoke plate with its bearing face down, upright and cheek lying on their clamp faces, cradle hub face down. They need no supports. Mount hub attachment uses the separately listed external mount hardware; do not buy it twice. ${p.mountThrough?'Install the hub with through bolts, washers and nuts in its front seats.':'Use M4 × 18 with one 1 mm washer through the 12 mm cradle: nominal 5 mm insert entry. Verify the actual stack and never bottom out.'}

Joints first. Heat-set the ${up.count+ch.count} M4 inserts: ${up.count} into the pilots in the bottom of the upright and ${ch.count} into the cheek's end face, each 0.5 mm below its tenon entry face (the tip of the 2 mm tenon), not below the surrounding shoulder. Let them cool and scrape off any raised rim so the faces stay flat. Drop the upright's 2 mm tenon into the matching pocket in the yoke plate (it locates against the shoulder on the inside) and drive the ${up.count} × M4 × ${up.length} flat-heads up through the plate from underneath. The heads must finish flush with or below the bottom face${base?', which is the azimuth bearing face':''}. Drop the cheek's 2 mm tenon into the pocket in the back of the cradle plate, so its end face and its two ribs sit flat on the plate, and fit it with the ${ch.count} × M4 × ${ch.length} flat-heads from the hub face, heads flush, before the dish hub goes on that face. Tighten firmly; do not strip the inserts.

${base===2?tripodText(m.mount.tripod):base?'Seat the M8 azimuth nut under the base before fixing the base to the stand with four M5 flat-head screws. Place the yoke on the base and fit M8 × 25 plus washer. ':'No base: put the yoke plate, upright already fitted, on a flat stand and drive four M5 flat-heads down through its countersinks, heads flush. Do this before the cradle goes on; the screws are reached from above beside the upright. There is no azimuth clamp without the base: set azimuth by turning or re-fixing the stand. The central 8.5 mm hole stays open. '}Seat the M8 × 40 hex head in the pocket inside the cheek, pass it through the upright, then fit the fender washer and wing nut. ${arc?`Arc lock: seat the M6 × ${F.arc.boltLength} head in the second pocket inside the cheek before offering the cradle up, so the bolt enters the upright's arc slot together with the M8. Fit the M6 washer and nyloc on the outside. To aim, loosen the nyloc and the wing nut, set the angle, tighten the wing nut, then snug the nyloc with a 10 mm wrench. The slot covers −10° to 100° and its ends stop travel just beyond. `:''}Hold the dish while loosening either axis. Aim by hand; these are friction clamps, not geared drives.

${base===2?tripodLimits(m.mount.tripod):''}Selected pose: azimuth ${p.azimuth}°, elevation ${p.elevation}°. Geometric clearance below ${below} is ${m.mount.standClearance.toFixed(1)} mm at this pose. The geometric requirement across the displayed elevation range is ${m.mount.sweepStandClearance.toFixed(1)} mm below ${below}; add a practical margin for the stand, cable and handling. Changing elevation changes this requirement. The generator checks printed-part interference at the selected pose, not the full movement path, stand, hardware or cable envelope. Plan the sweep before moving. ${base?'Azimuth hex-key access is limited: set elevation approximately 0–30° to adjust it. ':''}The 30 mm hub opening and 34 mm cradle port remain accessible; route and strain-relieve cables before aiming.

ASA or a qualified reinforced ASA can be considered for rigid mount parts using the supplier profile, 5–6 walls and locally solid clamp/bolt zones. This is separate from the flexible clip material choice. Test clamp slip and creep under the actual mass and temperature, and check the insert joints for creep and loosening along with the clamps. No load or wind rating is established for the clamps, the inserts or the joints. Do not compensate for slip by indefinitely increasing torque; inspect and revise the clamp or add a suitable metal load path.`;}
const tripodText=t=>{const b=t.bolt,f=x=>+x.toFixed(1);return `Tripod: seat the M8 azimuth nut in the pocket under the base, place the yoke on the base and fit M8 × 25 plus washer. Push each Ø${+t.d.toFixed(2)} mm leg fully into its socket (${f(t.engagement)} mm), drill Ø${b.size+.2} through the leg using the socket's cross hole as the guide, and fit M${b.size} × ${b.length} with a washer on each flat and a nyloc. Leg 1 points along the azimuth-zero direction; point it toward where the dish spends most of its time. `;};
const tripodLimits=t=>`Leg sockets: ${t.splay}° splay, Ø${+t.bore.toFixed(1)} mm bores ${+t.engagement.toFixed(1)} mm deep, walls ${+t.rootWall.toFixed(1)} mm at the base tapering to ${+t.tipWall.toFixed(1)} mm at the mouth. With ${t.minLegLength} mm legs the feet sit on a ${Math.round(2*t.footRadius)} mm circle and the base stands ${Math.round(t.height)} mm up. At that length the tripod's weakest edge sits ${TRIPOD.stability} times farther out than the worst center-of-mass offset over the elevation range (${Math.round(t.comOffset)} mm), and the dish stays ${TRIPOD.ground} mm off the ground. This is a static check only: no wind rating. Stake or weight the feet outdoors. ${t.blocked?`The dish reaches a leg between ${t.blocked[0]}° and ${t.blocked[1]}° elevation when facing it; aim above ${t.clearFrom}° or between legs.`:'The dish clears the legs at every azimuth and elevation.'} `;
